def main_solution(num1, num2, num3):
    product = num1 * num2 * num3
    is_multiple_of_3 = product % 3
    even_count = 0
    for n in [num1, num2, num3]:
        if n % 2 == 0:
            even_count += 1
    return {"is_multiple_of_3": is_multiple_of_3, "even_count": even_count}
