def main_solution(operations):
    # Initialize the map
    map_state = {}

    for op in operations:
        action = op['action']
        key = op['key']
        value = op['value'] if action == 'add' or action == 'modify' else None

        if action == 'add':
            map_state[key] = value
        elif action == 'delete':
            if key in map_state:
                map_state.pop(key)
        elif action == 'modify':
            if key in map_state:
                map_state[key] = value

    return map_state

