def main_solution(test_cases):
    results = []
    for i in range(len(test_cases)):
        if len(test_cases[i]) == 0:
            results.append("NO")
        else:
            # Check if all numbers are unique and no prefix exists
            unique = set()
            for num in test_cases[i]:
                if num in unique:
                    results.append("NO")
                    break
            unique = set()
            results.append("YES")
            return results

